  top: 0;
  width: 800px;
  height: 600px;
  position: fixed;
  right: 0;
  transform: translate(60%, 50%) rotate(30deg);
  background-image: radial-gradient(farthest-side, var(--blue-3), transparent);
}

@media (max-width: 640px) {
  .bg-gradient-blue-left, .bg-gradient-green-right, .bg-gradient-blue-right, .bg-gradient-green-left {
    display: none;
  }
}

.lp-page-container {
  min-height: 100vh;
  position: relative;

  .dashed-pattern-left {
    position: absolute;
    left: -1rem;
    top: 0;
    height: 100%;
    width: 1rem;
    opacity: 1;
    pointer-events: none;
    border-right: 1px solid var(--grayscale-5);
    mask: linear-gradient(to bottom, transparent 0%, rgba(0,0,0,1) 10%, rgba(0,0,0,1) 90%, rgba(0,0,0,0 ) 100%);
    -webkit-mask: linear-gradient(to bottom, transparent 0%, rgba(0,0,0,1) 10%, rgba(0,0,0,1) 90%, rgba(0,0,0,0) 100%);
  }

  .dashed-pattern-right {
    position: absolute;
    right: -1rem;
    top: 0;
    height: 100%;
    width: 1rem;
    opacity: 1;
    pointer-events: none;
    border-left: 1px solid var(--grayscale-5);
    mask: linear-gradient(to bottom, transparent 0%, rgba(0,0,0,1) 10%, rgba(0,0,0,1) 90%, rgba(0,0,0,0) 100%);
    -webkit-mask: linear-gradient(to bottom, transparent 0%, rgba(0,0,0,1) 10%, rgba(0,0,0,1) 90%, rgba(0,0,0,0) 100%);
  }

  .main-content {
    max-width: 60rem;
    margin: 0 auto;
    position: relative;
    padding: 3rem 0;
  }

  .hero-section {
    margin-bottom: 3rem;
  }

  .hero-title-container {
    margin-bottom: 2rem;
    padding: 0 2rem;
  }

  .hero-title {
    font-size: 2.25rem;
    font-weight: bold;
    letter-spacing: -0.025em;
    color: var(--grayscale-12);
  }

  .hero-description {
    font-size: 1rem;
    color: var(--grayscale-10);
  }

  .feature-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
  }

  .sdks-card {
    border-top: 1px solid var(--grayscale-5);
    padding: 2rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    grid-column: 1 / 2;
    grid-row: 1 / 2;
  }

  .docs-card {
    border-top: 1px solid var(--grayscale-5);
    border-left: 1px solid var(--grayscale-5);
    padding: 2rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    grid-row: 1 / 3;
  }

  .ai-search-card {
    border-top: 1px solid var(--grayscale-5);
    padding: 2rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
  }

  .card-header {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
  }

  .card-title {
    font-size: 1.25rem;
    font-weight: bold;
    color: var(--grayscale-12);
    display: flex;
    gap: 0.25rem;
    align-items: center;
    text-decoration: none;

    img {
      height: 1rem;
      opacity: 0;
      transition: opacity 0.15s ease-in-out, transform 0.15s ease-in-out;
      transform: translateX(0px);
    }

    &:hover {
      img {
        opacity: 1;
        transform: translateX(2px);
      }
    }
  }

  .card-description {
    font-size: 1rem;
    color: var(--grayscale-10);
  }

  .sdks-preview {
    width: 100%;
    position: relative;
  }

  .sdks-preview-img {
    width: 100%;
    object-fit: cover;
  }

  .docs-preview-img {
    width: 100%;
    object-fit: cover;
  }

  .ai-search-preview-img {
    width: 100%;
    object-fit: cover;
  }

  .language-icons {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .language-icons-label {
    font-size: 0.875rem;
    color: #62636c;
  }

  .language-icon {
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
    background: none;
    cursor: pointer;
    padding: 0;
    border-radius: 0.25rem;

    &:hover {
      background-color: var(--grayscale-a3);
    }
  }

  .language-icon-img {
    width: 16px;
    height: 16px;
    object-fit: contain;
  }

  .action-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
  }

  .action-buttons-vertical {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .community-section {
    border-top: 1px solid var(--grayscale-5);
    border-bottom: 1px solid var(--grayscale-5);
    padding: 3rem 2rem;
  }

  .community-title-container {
    margin-bottom: 2rem;
  }

  .community-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
  }

  .community-card {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0;
    align-items: flex-start;
  }

  .community-card-title {
    font-size: 1rem;
    font-weight: bold;
    color: var(--grayscale-12);
  }

  .community-card-description {
    font-size: 0.875rem;
    color: var(--grayscale-10);
    margin-bottom: 0.5rem;
  }

  .twitter-strikethrough {
    text-decoration: line-through;
  }

  .help-section {
    padding: 3rem 2rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  .help-buttons {
    display: flex;
    gap: 1.5rem;
  }

  .a-btn {
    text-decoration: none !important;
    font-weight: 400 !important;
    width: fit-content !important;

    img {
      transition: transform 0.15s ease-in-out;
      transform: translate(0px, 0px);
    }

    svg {
      display: none !important;
    }

    &.no-hover {
      cursor: default;

      &:hover {
        background: none !important;
        color: var(--grayscale-a11) !important;
      }
    }

    &:hover {
      img:not(:first-child) {
        transform: translate(2px, 0px);
      }
    }
  }

  /* Responsive Design - Mobile First */
  @media (max-width: 640px) {
    .main-content {
      padding: 2rem 1rem;
    }

    .dashed-pattern-left {
      left: 0px;
    }

    .dashed-pattern-right {
      right: 0px;
    }

    .hero-section {
      margin-bottom: 2rem;
    }

    .hero-title-container {
      padding: 0 1rem;
    }

    .feature-grid {
      grid-template-columns: 1fr;
      grid-template-rows: auto;
      gap: 0;
    }

    .sdks-card {
      padding: 1rem;
    }

    .docs-card {
      padding: 1rem;
      border-left: none;
      grid-column: 1;
      grid-row: auto;
    }

    .ai-search-card {
      padding: 1rem;
    }

    .card-title {
      font-size: 1.375rem;
    }

    .card-description {
      font-size: 1.0625rem;
    }

    .language-icons {
      flex-wrap: wrap;
      gap: 1rem;
    }

    .language-icons-label {
      width: 100%;
    }

    .language-icon {
      width: 2rem;
      height: 2rem;
      margin: -0.25rem;

      &:hover {
        background-color: var(--grayscale-a4);
        transform: scale(1.1);
        transition: all 0.2s ease;
      }
    }

    .language-icon-img {
      width: 20px;
      height: 20px;
    }

    .action-buttons {
      flex-direction: row;
      gap: 0.75rem;
      align-items: stretch;
      flex-wrap: wrap;
    }

    .action-buttons-vertical {
      gap: 0.75rem;
    }

    .community-section {
      padding: 2rem 1.5rem;
    }

    .community-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }

    .community-card {
      border-radius: 0.5rem;
      transition: all 0.2s ease;

      &:hover {
        border-color: var(--grayscale-6);
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
      }
    }

    .help-section {
      padding: 2rem 1.5rem;
    }

    .help-buttons {
      flex-direction: column;
      gap: 1rem;
    }


  }

  /* Tablet breakpoint - Better use of space */
  @media (max-width: 720px) and (min-width: 481px) {
    .community-grid {
      grid-template-columns: repeat(2, 1fr);
    }

    .hero-title {
      font-size: 2rem;
    }

    .feature-grid {
      gap: 1px;
    }
  }

  /* Very small screens */
  @media (max-width: 480px) {
    .hero-title {
      font-size: 1.75rem;
    }

    .card-title {
      font-size: 1.25rem;
    }

    .language-icon {
      width: 28px;
      height: 28px;
    }

    .language-icon-img {
      width: 16px;
      height: 16px;
    }
  }
}



.sdk-rive {
  aspect-ratio: 369/93;
  width: 100%;
  display: block;
  overflow: visible; /* Changed from hidden - was clipping interactive areas */
  transform: translateY(0px);
  transition: transform 250ms ease-out !important;
  will-change: transform;
  /* Ensure click events can reach the canvas */
  pointer-events: auto;
}

.sdk-rive:hover {
  transform: translateY(-3px) !important;
}

/* Ensure the canvas can receive clicks and is properly layered */
.rive-container {
  width: 100%;
  height: 100%;
  display: block;
  position: relative;
  /* Ensure container doesn't block events */
  pointer-events: none;
}

.rive-container canvas {
  width: 100%;
  height: 100%;
  vertical-align: baseline;
  display: inline-block;
  /* Allow canvas to receive events while container doesn't */
  pointer-events: auto !important;
  position: relative;
  z-index: 1;
  vertical-align: baseline;
  display: inline-block;
}

